import { adviceAddBundle, adviceAddItem } from "#base/ui/advice/advice-manager.js";
import { shouldSelect } from "#base/ui/advice/advice-support.js";

const TURN_WAIT = 20; // After how many turns when to select. (May be used with game speed to determine actual turn).
const TURN_START = 10; // On which turn should items start being selected (phased by turn offset).
const TURN_OFFSET = 4; // Which "phase" (from turn 1) to start checking.

adviceAddItem({
	id: "ADVICE_EXPLORATION_SCIENCE_SCIENTIFIC_VICTORY",
	type: AdvisorTypes.SCIENCE,
	onSelect: () => {
		return Game.turn == 1;
	},
});

adviceAddBundle({
	id: "ADVICE_EXPLORATION_SCIENCE_MISC",
	type: AdvisorTypes.SCIENCE,
	pages: [
		"ADVICE_EXPLORATION_SCIENCE_VICTORY_COUNTERPLAY",
		"ADVICE_EXPLORATION_SCIENCE_OVERBUILDING",
		"ADVICE_EXPLORATION_SCIENCE_TRIUMPH",
	],
	priority: 100,
	delivery: "random",
	onSelect: () => {
		return shouldSelect(TURN_START, TURN_WAIT, TURN_OFFSET);
	},
});
